import{_ as t,o as r,c as n,ag as s}from"./chunks/framework.CukOUUOK.js";const u=JSON.parse('{"title":"名与数：论权力对命名与点名的双重垄断","description":"本册构成 序列篇名处理的层总序命名与点名方法论别卷名实之间结构卷一批判的词汇如何变成辩护的盾牌名·机制卷二不可召集的多数数·夺取卷三占位的工会数·组织总问题：在何种条件下，一群人能够从「被讨论的对象」变成「采取行动的主体…","frontmatter":{"title":"名与数：论权力对命名与点名的双重垄断","categories":"政治思想史","tags":["权力","语言与文字","政治思想史","意识形态"],"description":"本册构成 序列篇名处理的层总序命名与点名方法论别卷名实之间结构卷一批判的词汇如何变成辩护的盾牌名·机制卷二不可召集的多数数·夺取卷三占位的工会数·组织总问题：在何种条件下，一群人能够从「被讨论的对象」变成「采取行动的主体…","date":"2026-09-24T12:00:00.000Z","series":"名与数：论权力对命名与点名的双重垄断","seriesOrder":1},"headers":[],"relativePath":"posts/2026-09-24-naming-and-numbers.md","filePath":"posts/2026-09-24-naming-and-numbers.md","lastUpdated":1790248139000}'),g={name:"posts/2026-09-24-naming-and-numbers.md"};function p(a,o,e,l,i,h){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="名与数-论权力对命名与点名的双重垄断" tabindex="-1">名与数：论权力对命名与点名的双重垄断 <a class="header-anchor" href="#名与数-论权力对命名与点名的双重垄断" aria-label="Permalink to &quot;名与数：论权力对命名与点名的双重垄断&quot;">​</a></h1><p><strong>本册构成</strong></p><p>序列篇名处理的层总序命名与点名方法论别卷名实之间结构卷一批判的词汇如何变成辩护的盾牌名·机制卷二不可召集的多数数·夺取卷三占位的工会数·组织<strong>总问题</strong>：在何种条件下，一群人能够从「被讨论的对象」变成「采取行动的主体」？</p><p><strong>核心命题</strong>：</p><blockquote><p><strong>名是定义权——我能不能用自己的词说清自己受的是什么。</strong> <strong>数是点名权——我能不能自己点出「我们」，并把点出来的人集合起来。</strong><br><strong>词被抽空 → 只剩下人数可靠 → 而点名的权力不在自己手里。</strong></p></blockquote><p><strong>三种权力操作</strong>：替你命名；替你统计；替你代表。三者指向同一个结果——你存在，但没有定义自己的权利；你人数庞大，但没有把自己集合起来的能力；你被完整代表，因此你不需要自己出现。</p><p><strong>关于编号</strong>：本系列原拟四卷，其中一卷在写作过程中被推翻、最终不立篇，故后续两卷顺延编号为卷二与卷三。详见总序第六节。</p><p><strong>阅读须知</strong>：本册为<strong>单案例的机制探查</strong>（n=1），应被读作<strong>待检验的假说集合</strong>，不是已确立的结论。核心概念（滑移、反向征用、占位、结构性收敛）均具解释弹性，已补判别式与证伪条件，但弹性无法根本消除。四类自我纠错见总序第八节；<strong>修订过程的逐条记录不入正文</strong>，另存为独立文件。</p><h2 id="总序" tabindex="-1">总序 <a class="header-anchor" href="#总序" aria-label="Permalink to &quot;总序&quot;">​</a></h2><h3 id="——从术语滑移到不可召集" tabindex="-1">——从术语滑移到不可召集 <a class="header-anchor" href="#——从术语滑移到不可召集" aria-label="Permalink to &quot;——从术语滑移到不可召集&quot;">​</a></h3><p><strong>系列名</strong>：《名与数：论权力对命名与点名的双重垄断》</p><h3 id="一、命名-为什么是-名-与-数" tabindex="-1">一、命名：为什么是”名”与”数” <a class="header-anchor" href="#一、命名-为什么是-名-与-数" aria-label="Permalink to &quot;一、命名：为什么是”名”与”数”&quot;">​</a></h3><p>这套文字最初没有名字。它从一对口号的比较开始（”外儒内法”与”外社内资”），中途拐进术语的语义学，最后落在平台骑手能不能把自己召集起来这个问题上。</p><p><strong>先说清一件事，以免本节被读作结构发现</strong>：各篇是分别写就后回头统稿的，写作过程中还发生过一次改向——后来编号为卷二的那一篇，推翻了原拟另一卷的方法前提，后者因此不立篇（详见第六节）。因此”它们一直在处理同一件事”是<strong>回溯性整合</strong>，不是事先的设计。<strong>读者有权把它当作事后叙事，本文承认这一点。</strong> 下面的”名”与”数”是统稿时发现的两个侧面，不是动笔时立下的框架。</p><p><strong>“名”</strong>，是正当化之维。名分、正名、名实之辩——中国政治思想里，”名”从来不只是称呼，它是秩序的说明书：君君、臣臣，各安其位，位由名定。谁掌握”名”，谁就掌握了描述现实的词汇表，也就掌握了什么可以被说、什么说出来就是错的。本系列的卷一处理的正是这个维度：一套批判性的词如何被抽空，从而失去伤及权力的能力。</p><p><strong>“数”</strong>，是集合之维。编户齐民、算赋口赋、户籍黄册、鱼鳞图册——”数”在中国治理传统里从来不只是数学，它是人口成为治理对象的那一刻：被登记、被计量、被按比例征发。</p><p><strong>但”数”在本系列中的含义必须收紧，否则它无法承担理论工作。</strong> 本系列此前把编户齐民、算法行为清点、工会会员名册三种东西都叫作”数”，而它们并不是同一种操作——这是本系列此前最重要的理论缺口。</p><p><strong>本册采用的统一定义是：数即点名权。</strong></p><blockquote><p><strong>点名权</strong>：把一个群体指认为”我们”、并把这个”我们”转化为共同行动的权力。</p></blockquote><p>之所以用”点名”而不是”统计”，是因为这个词同时包含了三件在治理中通常被分离的事：</p><ol><li><strong>清点</strong>——数得出来（可以是别人在数）；</li><li><strong>召集</strong>——点得齐（只能自己点）；</li><li><strong>代表</strong>——说了算（只能自己说）。</li></ol><p><strong>治理的技术进步，恰恰是把这三件事拆开：清点被做到了极致，召集与代表被留在了别人手里。</strong> “数”因此不是”统计”，而是”<strong>谁有权把你们点成一个我们</strong>“。</p><h3 id="两条维度如何统一" tabindex="-1">两条维度如何统一 <a class="header-anchor" href="#两条维度如何统一" aria-label="Permalink to &quot;两条维度如何统一&quot;">​</a></h3><p>修正之后，”名”与”数”不再是并列的两种管理，而是同一件事在两个层面上的操作：</p><blockquote><p><strong>名是定义权——我能不能用自己的词说清自己受的是什么。</strong> <strong>数是点名权——我能不能自己点出”我们”，并把点出来的人集合起来。</strong></p></blockquote><p>两者合起来，指向同一个判断：</p><blockquote><p><strong>权力不一定需要让人闭嘴。它可以允许你说话，只要规定你用什么词说；它也不一定需要让人消失，它可以精确地统计你、代表你、服务你，只要不让你自己出现。</strong></p></blockquote><p>抽空一个词，与夺走一次点名，是同一种操作的两端：<strong>前者让你说不出自己受的是什么，后者让你点不出自己是谁。</strong> 一个说不出、点不出的群体，在政治意义上等于不存在——它可以被大量引用，可以被精确统计，但它无法作为”我们”出现。</p><p>于是全系列的问题可以压缩成一个三步序列：</p><blockquote><p><strong>第一步，替你命名；第二步，替你统计；第三步，替你代表。</strong> <strong>结果：你存在，但你没有定义自己的权利；你人数庞大，但你没有把自己集合起来的能力；你被完整代表，因此你不需要自己出现。</strong></p></blockquote><p>这就是系列名的来历。**《名与数》**不是修辞，是对全篇论断的压缩：批判理论与政治实践的全部条件，都可以归为两条——<strong>能不能用自己的词说清自己的处境，能不能自己点一遍自己的名。</strong></p><h3 id="二、总问题-一个主体的生成条件" tabindex="-1">二、总问题：一个主体的生成条件 <a class="header-anchor" href="#二、总问题-一个主体的生成条件" aria-label="Permalink to &quot;二、总问题：一个主体的生成条件&quot;">​</a></h3><p>四篇有一个共同的总问题，可以精确表述为：</p><blockquote><p><strong>在何种条件下，一群人能够从”被讨论的对象”变成”采取行动的主体”？</strong></p></blockquote><p>这个问题之所以值得单独提出，是因为人们太容易把它替换成一个看似相同、实则弱得多的问题——”在这一条件下，他们的处境有没有改善？”</p><p>这两个问题的答案经常相反，而本系列的全部工作，就是把这个”相反”拆开给人看。</p><p>卷二的材料是这个相反的最纯粹形态，但它必须被准确陈述。<strong>2021 年 2 月 18 日，一名骑手发布视频指出平台悄悄提高了奖励门槛；2 月 19 日，平台公开致歉并整改；2 月 25 日，该骑手被带走。</strong></p><p>这三点是本案唯一不需要推论即可读出的事实。<strong>它们是三个不同行动者的行为</strong>：前两步是公司行为，第三步是执法行为。<strong>本文没有材料证明其间存在因果关联</strong>，因此不写”系统接受了内容、拒绝了主体”——那是把一个匿名主语缝合进两个各自独立的过程。</p><p>可陈述的只有<strong>结果结构</strong>：诉求的内容被接受了，提出诉求的节点被移除了。而这个结果<strong>不需要假定一个统一行动者</strong>——公司接受一次性条款调整（成本可计算、可分摊），执法机关移除一个不可控的召集节点，两者可以各自成立。</p><p><strong>“谁在决策”本文无法回答；本文能回答的是”什么被留下了”。</strong></p><p>卷二的材料是同一个相反的制度化形态：<strong>2331 万人</strong>（存量口径）被登记为会员；而覆盖 <strong>2500 万人</strong>（规划目标口径，非实测）的算法协商，其劳动者一方代表的下限由该规划设定为不少于 5 名。<strong>两个数字口径不同，不能相加，也不能直接互比</strong>（卷二 7.1 节列有完整口径表）。这里可陈述的只是：登记极其精确，而在本文所考察的通道内，主体未以被召集者的身份出现过。</p><p>于是总问题可以再收紧一层：</p><blockquote><p><strong>改善与主体化，不仅不是同一件事，而且在特定结构下互为代价——改善越是经由”不需要主体在场”的路径达成，主体就越不会生成。</strong></p></blockquote><p><strong>这是本系列的核心命题，但必须承认：它在各篇中被断言了至少四次，而因果机制长期没有给出。</strong> 现在补上——三条可分别检验的链条：</p><p><strong>链条一（替代）：</strong> 不需主体在场的改善，为不满提供了一个<strong>无需组织的出口</strong>。当诉求可通过投诉、热线、平台内申诉、监管介入获得部分满足时，集体行动这一成本更高的路径即被绕过。 <strong>链条二（降需）：</strong> 改善降低了不满强度，从而降低主体化的<strong>动机</strong>。这不需要任何人的设计——它是改善本身的效果。 <strong>链条三（坐实）：</strong> 由他人提出、他人决定、他人撤回的改善，在每次发生时都<strong>再生产一次”被代表”的格局</strong>，使”自己提出”这一选项在经验上从未被演练。</p><p><strong>三条链条的指标问题必须承认，否则它们只是装饰。</strong> 上列”可检验指标”（如”自我组织能力的存量不增加，则链条三成立”）是<strong>肯定后件结构</strong>：存量不增有一千种原因，链条三只是其中之一。三条链的指标只能显示相关，<strong>不能在诸链之间做区分</strong>——它们是存在性证据，不是判别性证据。</p><p><strong>更严重的质疑是：三条链与本系列的主要案例对不上。</strong> 必须把”对不上”的原因说准，否则自我批评会打偏：</p><ul><li>本案中的改善（2 月 19 日平台致歉整改）<strong>恰恰是由主体本人的行为触发的</strong>（2 月 18 日的视频），而不是”由他人提出、他人决定”——链条三的前提在此不成立。</li><li>该骑手的联盟成立于 2019–2020 年，<strong>先于</strong>这里所说的任何改善发生——链条一（改善替代了组织）在时序上也套不上。</li></ul><p>因此准确的表述不是”本案证伪了链条一与链条三”，而是：<strong>本案不在两条链条的适用范围内</strong>。本系列的主要证据检验不了它们。</p><p>修正后的处置：三条链条降级为<strong>候选机制清单</strong>，且本文承认<strong>它们在本系列现有材料上无法被检验</strong>（既不能证实，也不能证伪）。这不是”遇到反例”，是<strong>没有适格的证据</strong>——后者比前者更彻底，也更难堪：<strong>一个在自己唯一案例上都不适用的因果主张，连”待检验”都算勉强。</strong></p><p>本系列不作处境是否改善的价值裁决，只追问：<strong>改善由谁提出、由谁决定、由谁撤回。</strong> 一个只能由他人提出、他人决定、他人撤回的改善，在定义上是恩惠，不是权利。</p><p><strong>但必须承认一处承诺与执行的不一致</strong>：本系列多处使用了”不生产主体”“产得出条款产不出主体”这类措辞。<strong>这已经是降格裁决，与”不作裁决”的承诺冲突。</strong> 修正：此类措辞此后一律读作<strong>条件描述</strong>（”该路径不要求主体在场”），而非价值评价（”该路径低一等”）。</p><h3 id="三、四卷的推进" tabindex="-1">三、四卷的推进 <a class="header-anchor" href="#三、四卷的推进" aria-label="Permalink to &quot;三、四卷的推进&quot;">​</a></h3><p>卷篇名处理的层核心概念结论别卷《名实之间》结构名实分离、外儒内法／外社—资—权名实分离是功能性结构，不是骗术；以解放为名的话语内含自我引爆的引信（本系列原拟四卷，其中一卷在写作中被推翻、最终不立篇，故后续两卷顺延编号为卷二、卷三。上表不列该卷，说明见第六节。） | <strong>卷一</strong> | 《批判的词汇如何变成辩护的盾牌》 | 名·机制 | 术语滑移、反向征用 | 引信不是被拆除的，是被抽空的；批判词被调转枪口，从武器变成盾牌 | | <strong>卷二</strong> | 《不可召集的多数》 | 数·夺取 | 形式供给、点名权三环节 | 被高度清点，而自我召集的通道缺位；无壳与壳不可入 | | <strong>卷三</strong> | 《占位的工会》 | 数·组织 | 占位（国家法团主义的中文工作名）、财政依附、名册化悖论 | 点名权由他人完成：代表越完整，治理者对”被治者自行集合”的依赖越低；被治者一端能否召集，本文未测量 |</p><p>推进的逻辑是一条单线，可以压缩成三句话：</p><ol><li><strong>卷一处理”名”的失效</strong>：一套批判性的词如何在不删改任何一字的前提下失去力量——不是让它闭嘴，而是让它转向。</li><li><strong>卷二处理”数”的夺取</strong>：当词已经不可靠，唯一还能构成力量的就是人数；而法律形式供给决定了这个人数能否被自己清点。</li><li><strong>卷三处理”数”的组织形态</strong>：点名不是自发发生的，它有主体——一个占据位置、替所有人报到、从而使所有人不必再自己集合的组织。</li></ol><p>三句话合起来，就是本系列的完整论证链条：</p><blockquote><p><strong>词被抽空 → 只剩下人数可靠 → 而点名的权力不在自己手里。</strong></p></blockquote><p><strong>一处账目必须重算</strong>：卷三 2.1 节已认领施密特（Philippe Schmitter）的国家法团主义，并明确”占位”是”中文工作名，不是一个新发现的理论”。因此上表中”占位”不再列为理论贡献，只列为<strong>分析工具</strong>。本系列的理论贡献应被重新表述为三项，且强度均有限：</p><ol><li><strong>点名权三分</strong>（清点／召集／代表的可分离性）——这是本系列最实的贡献；</li><li><strong>改善与主体化的分离</strong>——作为一个观察框架，不是因果规律（见第二节的自限）；</li><li><strong>形式供给假说</strong>（无壳／壳不可入）——作为待检验假说。</li></ol><p>别卷《名实之间》的位置需要说明。它不在编号序列内，因为它处理的是<strong>宏观结构</strong>（两种名实分离形态的比较），而正编四卷处理的是<strong>微观机制</strong>（具体的语言机制与法律机制）。二者共享”名实分离”这个总问题，但层级不同：别卷论证”为什么需要名”，正编论证”名如何失效、数如何被夺”。引用时宜注明组别。</p><h3 id="四、统一的方法论-三把尺子" tabindex="-1">四、统一的方法论：三把尺子 <a class="header-anchor" href="#四、统一的方法论-三把尺子" aria-label="Permalink to &quot;四、统一的方法论：三把尺子&quot;">​</a></h3><p>四篇各自发展了一套判据。单独看，它们是四篇的工具；放在一起，它们构成一个完整的检验工具箱——<strong>词、制度、主体</strong>三个层次，各有一把尺。</p><h3 id="_4-1-验词-三关-卷一" tabindex="-1">4.1 验词：三关（卷一） <a class="header-anchor" href="#_4-1-验词-三关-卷一" aria-label="Permalink to &quot;4.1 验词：三关（卷一）&quot;">​</a></h3><p>检验一个术语是否还有生命力：</p><ol><li><strong>是否指向可观察、可测量的关系？</strong> ——”存在雇佣劳动关系、资本集中趋势”可查；”这是资本主义”不可查。</li><li><strong>能否做出有风险的预测？</strong> ——是否存在能推翻它的事实。</li><li><strong>换了个词，解释力会不会变？</strong> ——加定语是否带来新机制，还是只是术语通胀。</li></ol><p>配套方法：用<strong>关系句</strong>代替名词。<strong>但关系句的作用须准确描述</strong>：它不免疫于再解释（每个成分都可被重新定义，判定权不因改写而转移），其可靠功能是<strong>留下记录</strong>——把”我看见了什么”换成”需要查什么”，使后来者不必重新相信，只需重新核查。<strong>不忠诚于词，只忠诚于可检验的关系；而”可检验”指可被他人复核，不指它能保护你。</strong></p><h3 id="_4-2-验壳-三问-卷二" tabindex="-1">4.2 验壳：三问（卷二） <a class="header-anchor" href="#_4-2-验壳-三问-卷二" aria-label="Permalink to &quot;4.2 验壳：三问（卷二）&quot;">​</a></h3><p>检验一个制度外壳是否真实：</p><ol><li><strong>能否不经许可进入？</strong>（准入）——需要批准才能成立的主体，其存在本身就是被授予的。</li><li><strong>能否说”不”？</strong>（对抗）——只能同意、不能拒绝的席位，是咨询席位，不是议价席位。</li><li><strong>说”不”之后能否存活？</strong>（存续）——若对抗的代价由该主体独自承担且无法被制度吸收，第二问的”能”就是假的。</li></ol><h3 id="_4-3-验主体-点名权三问-卷二、卷三" tabindex="-1">4.3 验主体：点名权三问（卷二、卷三） <a class="header-anchor" href="#_4-3-验主体-点名权三问-卷二、卷三" aria-label="Permalink to &quot;4.3 验主体：点名权三问（卷二、卷三）&quot;">​</a></h3><p>检验一个群体是否可能成为主体，不是看两个量的相关关系，而是问一句<strong>谁在点名</strong>。</p><blockquote><p><strong>点名权</strong>：把一个群体指认为”我们”、并把这个”我们”转化为共同行动的权力。</p></blockquote><p>它包含三个可分别检验的环节：</p><p>环节问的是由谁完成清点这个群体有多少人？能不能被数出来？可以是治理者，也可以是群体自己召集这些人能不能集合？只能是群体自己代表集合起来的”我们”能不能提出、决定、撤回？只能是群体自己<strong>关键的不对称性就在这里</strong>：清点可以由他人代劳，召集与代表不能。<strong>一个被他人完整清点、完整代表的群体，可以始终没有点过自己的名。</strong></p><p>因此本文不再主张”可清点性与可召集性呈反向关系”——<strong>该说法已被卷二、卷三撤回</strong>（单点观察不支持函数关系，确立负相关需要跨案例对照，本文一个对照群体也没有）。修正后的命题是一个<strong>制度功能命题</strong>，不是因果命题：</p><blockquote><p><strong>清点可以让治理者不再需要被治者自己集合。</strong> 治理系统获得了足够精细的信息与代表结构，便可在不等待群体自行集合的情况下处理群体问题。</p></blockquote><p>这比因果命题更冷，也更强：<strong>它不需要证明任何人在阻止你组织，只需要证明——集合这一步骤，对治理者而言已经可以省略。</strong></p><p><strong>证伪条件</strong>：若能观察到一个被高度清点的群体，同时具备畅通的自我召集通道，则本文命题不成立。</p><h3 id="_4-4-三把尺的同构性" tabindex="-1">4.4 三把尺的同构性 <a class="header-anchor" href="#_4-4-三把尺的同构性" aria-label="Permalink to &quot;4.4 三把尺的同构性&quot;">​</a></h3><p><strong>一项关于三把尺的论断须予撤回。</strong> 若称三把尺”问的是同一个问题”，并用”共同敌人是不可证伪性”把它们焊成一把，<strong>这不成立</strong>：</p><ul><li><strong>验词三关是认识论判据</strong>——问的是”能否被事实推翻”；</li><li><strong>验壳三问是规范—制度判据</strong>——问的是”能否说不、说了能否存活”。其中第二、三问涉及权利与风险分配，是<strong>规范判断</strong>，与可证伪主义无关；</li><li><strong>可清点／可召集是一对描述性指标</strong>，问的是”两者关系如何”，本身不含判准。</li></ul><p><strong>用”共同敌人是不可证伪性”把三类判据统一，是表面工整的修辞操作。</strong> 更尴尬的是：这条元判据本身不可证伪——<strong>“凡不可被检验的都已经死了”这句话，如何被检验？</strong></p><p>修正后，三把尺的关系应被准确描述为：<strong>它们不是一把尺的三个刻度，而是三把用途不同的尺，共同覆盖”词—制度—主体”三个层次。</strong> 它们之间的关系是<strong>分工</strong>，不是同构。本文不再主张它们可以合并。</p><p>而三把尺共用同一条更冷的前提（卷二、卷三反复验证）：</p><blockquote><p><strong>可撤回性不仅是一种制度设计，也是一种风险分配。如果撤回的代价全部落在撤回者身上，再精巧的设计也不会被使用。</strong></p></blockquote><h3 id="五、系列的自我限定" tabindex="-1">五、系列的自我限定 <a class="header-anchor" href="#五、系列的自我限定" aria-label="Permalink to &quot;五、系列的自我限定&quot;">​</a></h3><p>本系列有四处分明的薄弱点，必须在总序中主动交代，否则全文的批判力度会被它们反噬。</p><h3 id="_5-1-材料的不对称风险" tabindex="-1">5.1 材料的不对称风险 <a class="header-anchor" href="#_5-1-材料的不对称风险" aria-label="Permalink to &quot;5.1 材料的不对称风险&quot;">​</a></h3><p>卷二的核心案例（陈国江案）<strong>最终处置结果无可靠公开信息</strong>，本文已明确不作断言；卷二所引的悉尼对照材料<strong>未经独立核实</strong>，已降级为不参与推论的对照假设。这意味着：卷二的经验基础比它的论证强度所能要求的要薄。</p><p>处理方式与代价都需要说明：<strong>处理方式是只用可核查部分承重，把待验证材料隔离；代价是本系列因此无法回答”实际发生率”这一关键问题</strong>——它能论证某一机制的存在与结构位置，不能论证该机制的普遍程度。<strong>这是机制研究，不是频率研究。</strong></p><p><strong>但”机制研究”这一自我豁免不能过宽。</strong> 机制研究至少需要显示机制的<strong>重复性</strong>；而本系列的实际证据是 <strong>n=1</strong>（陈国江案）加一则已删除的不可信对照。<strong>因此本系列更准确的自我定位是：单案例的机制探查（mechanism probing），不是机制确立。</strong> 相应地，本系列已全面清除”永远”“从来”“最先退出的永远是”一类无限量词——<strong>n=1 的材料配”永远”的量词，不是谨慎，是叙事的需要。</strong> 凡原稿出现此类量词处，均已改为可检验的预期陈述。</p><h3 id="_5-2-对称性论证的代价" tabindex="-1">5.2 对称性论证的代价 <a class="header-anchor" href="#_5-2-对称性论证的代价" aria-label="Permalink to &quot;5.2 对称性论证的代价&quot;">​</a></h3><p>为免沦为单向指控，别卷、卷一、卷二、卷三都设置了对称性章节（西方的镜像操作、米歇尔斯铁律、商业工会主义、日本企业工会）。这一处理的收益是比较分析的锋利度，代价是<strong>批判的精度被稀释</strong>：当”双方都在做”成为论证的一部分时，对特定法域的具体批判就不可避免地变钝了。</p><p>本文对此的处理是给出可逆性判据（卷三第八节）：<strong>退化的寡头可被会员激活，先天的占位不能。</strong> 这是一条试图在承认普遍性的同时保留具体批判力的路径，但它是否足够，读者可自行判断。</p><h3 id="_5-3-理论来源的内在张力" tabindex="-1">5.3 理论来源的内在张力 <a class="header-anchor" href="#_5-3-理论来源的内在张力" aria-label="Permalink to &quot;5.3 理论来源的内在张力&quot;">​</a></h3><p>本系列大量使用马克思，而马克思所批判的对象恰恰自称马克思主义。这产生一个无法回避的循环：<strong>用一套词汇批判以该词汇为合法性来源的体系，批判的效力取决于词汇是否还被相信。</strong> 如果词汇已经彻底失去公信力（卷一第九节所述的犬儒主义），批判就失去了着力点——你对着一面已经没人读的旗子挥拳。</p><p>卷一的回应是”自反性检验”（第八节）：承认马克思文本自身即埋有滑移的种子，<strong>并首先把判据用在自己身上</strong>。这是本文能给出的唯一回应，它不完美，但它是诚实的。</p><h3 id="_5-4-结构解释的责任缺口" tabindex="-1">5.4 结构解释的责任缺口 <a class="header-anchor" href="#_5-4-结构解释的责任缺口" aria-label="Permalink to &quot;5.4 结构解释的责任缺口&quot;">​</a></h3><p>本系列反复使用”结构性收敛”而非”共谋”作为解释。这个选择在分析上更稳健（它解释了为什么更换行动者无法移动均衡），但它带来一个道德与政治上的代价：</p><blockquote><p><strong>如果问题出在激励的几何形状，就没有人需要负责。</strong></p></blockquote><p>一个没有责任者的批判，很难转化为任何行动。这是本系列最大的无力之处，也是一个必须承认的缺口——<strong>它解释得越成功，越难被问责。</strong></p><h3 id="六、关于编号-一次删减与一次重编" tabindex="-1">六、关于编号：一次删减与一次重编 <a class="header-anchor" href="#六、关于编号-一次删减与一次重编" aria-label="Permalink to &quot;六、关于编号：一次删减与一次重编&quot;">​</a></h3><p>本系列现为<strong>别卷一篇、正编三篇</strong>（卷一、卷二、卷三）。编号中的空位不在末尾，而在写作史里——这里把它交代清楚，因为它牵涉一个方法论问题。</p><p><strong>原拟的第二卷</strong>处理”平台劳动改善的来源”，其核心判断是：改善主要来自法律与行政技术，而非阶级意识觉醒；由此提出三项方案。</p><p><strong>这个判断的方法前提被后来编号为卷二的那一篇推翻了。</strong> 卷二指出：同一套法律同时是决定”多少人可以一起说话”的力量——它既改善条款，也封锁形式。这不是补充，是改向。</p><p>此后曾一度将原拟的一卷补写成篇，随后撤回。撤回的理由是一条编辑原则：</p><blockquote><p><strong>一篇文章的存在理由，是它说了别处没有说的东西。</strong></p></blockquote><p>它没能通过。仍成立的部分——改善来自条款而非运动、参数层开放与结构层封闭、三项方案及其修正——<strong>已全部由卷二、卷三消化并重述</strong>；剩下的只是一个被推翻前提的完整论证，以及一份说明它如何被推翻的附录。为填补编号而保留这样一篇，是<strong>为形式完整而制造内容</strong>——这正是本册在别卷中批判过的操作。</p><p>因此该卷不立篇，后续两卷顺延编号为<strong>卷二</strong>（原卷三《不可召集的多数》）与<strong>卷三</strong>（原卷四《占位的工会》）。卷二的开篇即完整陈述被推翻的那个判断，<strong>读者无需另寻文本</strong>；各卷中凡涉及该判断处，均直接写出命题本身，不使用指向不存在文本的指称。</p><p>下表列出这些判断的命运，供读者核对卷二、卷三究竟消化了什么。<strong>须准确理解</strong>：”保留／推翻／修正”的三分法由<strong>作者一人自任法官</strong>，推翻者与被推翻者出自同一人之手，无外部检验——<strong>这是自我推翻</strong>，其认识论价值等于”我今天否定我昨天的想法”，只是被写成了表格。读者应把它当作<strong>作者自述的工作记录</strong>，不当作经过核定的结论。</p><p>原拟卷的判断后续命运平台劳动条件的改善主要来自法律与行政技术，而非阶级意识觉醒保留，作为卷二的问题起点法律是偏向劳动者的外生杠杆／”法律可以是运动的放大器”推翻——卷二认定其为实质性偏差：法律同时是决定”多少人可以一起说话”的力量改良停留在参数层面，结构层面封闭（”议程无权”）修正——卷二补充：结构之所以封闭，是因为试图把参数问题升级为结构问题的人会消失欧盟举证责任倒置”不需要主体在场就能生效”保留并升格，成为卷二、卷三的核心判据：正因不需要主体在场，它就不要求主体在场三项方案（重造可召集性／代表性移入规制／绘制问责链）修正——卷二加上风险分配前提；卷三指出三条均属止损而非解法清点下来：事实判断成立并保留，方法判断被推翻，三项方案被修正。<strong>所有仍成立的部分都已在卷二、卷三中重述</strong>——这就是它不必单独成篇的完整理由。</p><blockquote><p><strong>这个顺序值得注意：本系列不是先有完整设计再逐篇执行，而是在写作中推翻了自己此前的前提。保留这个推翻的痕迹，比事后把它抹平更诚实——所以编号顺延，而不是把空缺抹去。</strong></p></blockquote><h3 id="七、收口-名与数-回到谁手里" tabindex="-1">七、收口：名与数，回到谁手里 <a class="header-anchor" href="#七、收口-名与数-回到谁手里" aria-label="Permalink to &quot;七、收口：名与数，回到谁手里&quot;">​</a></h3><p>最后把整个系列扣回它的名字。</p><p>马克思的原意，本系列在卷二结尾引用过一次，这里再引一次并作补正：</p><blockquote><p><strong>他从不相信概念能解放谁，他只相信能被清点的人数。</strong></p></blockquote><p>卷二对此的补正是：</p><blockquote><p><strong>能被清点，还不够。要能被自己清点，并且能被自己召集。前者是统计，后者才是政治。</strong></p></blockquote><p>用《名与数》的术语重述，这句话就是本系列的最终命题：</p><ul><li><strong>“名”回到自己手里</strong>——能用未经抽空的词说清自己受的是什么（卷一的”关系句”）；</li><li><strong>“数”回到自己手里</strong>——能自己数一遍自己，并且数出来的数字能被用于集合（卷二的”可召集性”、卷三的”占位”批判）。</li></ul><p><strong>一处跨卷一致性问题：</strong> 卷二称”‘人民’的最终形态是卷一所述语义滑移的终点”，并把”人民”编入卷一的术语演化谱系。<strong>这一谱系不成立</strong>：卷一处理的术语清单是资本主义、剥削、异化、市民社会、社会主义——<strong>“人民”根本不在其中</strong>。把一个未被卷一处理过的词，说成卷一所述过程的终点，是两个不同对象被强行焊进同一条演化链。</p><p>修正后，卷二的相关论断应被读作<strong>独立的平行主张</strong>，而非卷一的推论：<strong>“人民”一词在统计上被高度引用、在程序上不可召集——这是一个可直接观察的现象，不需要经由卷一的滑移机制来证明。</strong> 卷一与卷二因此是<strong>并置的两条证据</strong>，不是一条因果链上的两端。</p><p><strong>本系列并未执行自己立下的语言法。</strong> 卷一宣布关系句是”批判理论在术语层面唯一可靠的自我保存方式”，并立法要求用关系句代替名词。<strong>但卷二、卷三通篇未对任何自身命题做过关系句改写</strong>——”占位”“名册化”“壳”“反向征用”全是隐喻密集的概念。<strong>本系列的分析语言没有执行自己立下的语言法。</strong></p><p>补做一次，就补在本系列的三个核心概念上（这是本系列第一次对自己执行自己的规则）：</p><p>隐喻写法关系句改写“术语被抽空”某词在公共文本中的出现频率上升，而其可检验成分（所指关系、测量方式、判定主体）的出现频率下降；且批判性用法被抑制的比例高于辩护性用法“批判词变成盾牌”该词的批判性用法在指向本地对象时被抑制，在指向外部对象时被鼓励；两种用法的判定由同一机构作出“工会占位”存在一个由上一级机构批准产生的组织；该组织享有本类别内的唯一代表资格；该资格不由被代表者授予，也不由被代表者撤回改写之后立刻可以看出：<strong>三句关系句都比原隐喻弱，且都需要测量才能成立</strong>。这正是关系句的价值——它把”我看见了什么”换成”需要查什么”。<strong>本系列此前拒绝这样写自己，是因为这样写过之后，结论会显得没有把握。这本身就是答案的一部分。</strong></p><p>两者缺一不可，且互相依赖：<strong>说不清自己处境的人，即使被召集也不知要什么；数不出自己人数的人，即使说清了也没有力量。</strong></p><p>而四篇所记录的全部机制——术语滑移、反向征用、形式封锁、壳不可入、财政依附、名册化——<strong>都可以归为同一种操作的不同手法：阻止”名”与”数”同时回到同一个人手里。</strong></p><blockquote><p>让你说得清、数不出（卷一 + 卷二）； 或者让你数得清、说不出（卷三的名册化）； 最经济的做法是：替你说、替你数，于是你既不必说，也不必数（卷三的占位）。</p></blockquote><p>三种手法，同一个结果：<strong>一个在统计上庞大、在话语上被高频引用、在程序上从未出现的”人民”。</strong></p><p><strong>一处公开更正。</strong> 本系列曾以这样一个句子收尾：<strong>“在那几天，北京的外卖订单没人接。”</strong> 它在总序与卷二结论中两次出现，两次都被冠以”可核查的事实”，并承担了全系列的修辞地基。</p><p><strong>经核，该句没有任何公开来源，且与卷二第二节自述的事实相冲突</strong>（2019 年的轮流停送”行动尚未展开即告终止”；2021 年事件中亦无停送报道）。<strong>它已从本册删除。</strong></p><p>替代它的，是卷二结论中真正可核查的那一段：<strong>2021 年 2 月 18 日发布视频指出规则被悄悄提高→2 月 19 日平台致歉整改→2 月 25 日被带走。</strong> 诉求在一天内被接受，提出诉求的人在一周内被移除。</p><p><strong>这三点是本案唯一不需要推论即可读出的事实。</strong> 一个建立在无源事实上的收尾，比没有收尾更糟——本系列现在有一个更短、但真的收尾。</p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2086507746279551235" target="_blank" rel="noreferrer">查看原文</a></p></blockquote>',136)])])}const b=t(g,[["render",p]]);export{u as __pageData,b as default};
